@app.get("/api/integration/tickets/{ticket_id}/status")
def ticket_status_json(ticket_id: int, x_api_key: str = Header(...), db: DbSession = Depends(get_db)):
    if not authenticate_api_key(db, x_api_key):
        raise HTTPException(status_code=401, detail="Invalid API key")
    ticket = db.get(MaintenanceTicket, ticket_id)
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    return {"ticket_id": ticket.id, "status": ticket.status, "updated_at": ticket.updated_at.isoformat()}

