@app.patch("/api/inspections/{inspection_id}")
def update_inspection(inspection_id: int, payload: InspectionUpdateIn, request: Request, db: DbSession = Depends(get_db), user: User = Depends(current_user)):
    inspection = db.get(Inspection, inspection_id)
    if not inspection:
        raise HTTPException(status_code=404, detail="Inspection not found")
    ensure_inspection_scope(db, user, inspection)
    if payload.status and payload.status != inspection.status:
        if payload.status not in INSPECTION_TRANSITIONS.get(inspection.status, set()):
            raise HTTPException(status_code=400, detail=f"Cannot transition inspection from {inspection.status} to {payload.status}")
        inspection.status = payload.status
    if payload.findings is not None:
        inspection.findings = payload.findings
    if payload.follow_up_tasks is not None:
        inspection.follow_up_tasks = payload.follow_up_tasks
    if payload.tenant_visible is not None:
        inspection.tenant_visible = payload.tenant_visible

def ensure_inspection_scope(db: DbSession, user: User, inspection: Inspection) -> None:
    if user.role == Role.tenant.value:
        if not inspection.tenant_visible:
            raise HTTPException(status_code=403, detail="Inspection is internal")
        ensure_unit_scope(db, user, inspection.unit_id)
        return
